    n->next = NULL;
    return n;
}

void insert_beginning(Node** head, int data) {
    Node* n = create_node(data);
    n->next = *head;
    *head = n;
}

void insert_end(Node** head, int data) {
    Node* n = create_node(data);
    if (!*head) { *head = n; return; }
    Node* cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n;
}

bool insert_at_position(Node** head, int pos, int data) {
    if (pos < 1) return false;
    if (pos == 1) {
        insert_beginning(head, data);
        return true;
    }
    Node* cur = *head;
    for (int i = 1; cur && i < pos - 1; i++) {
        cur = cur->next;
    }
    if (!cur) return false;
    Node* n = create_node(data);
    n->next = cur->next;
    cur->next = n;
    return true;
}

bool delete_beginning(Node** head, int* val) {
    if (!*head) return false;
    Node* tmp = *head;
    *val = tmp->data;
    *head = (*head)->next;
    free(tmp);
    return true;
}

bool delete_end(Node** head, int* val) {
    if (!*head) return false;
    if (!(*head)->next) {
        *val = (*head)->data;
        free(*head);
        *head = NULL;
        return true;
    }
    Node* cur = *head;
    while (cur->next->next) cur = cur->next;
    *val = cur->next->data;
    free(cur->next);
    cur->next = NULL;
    return true;
}

bool delete_by_value(Node** head, int val) {
    if (!*head) return false;
    if ((*head)->data == val) {
        Node* tmp = *head;
        *head = (*head)->next;
        free(tmp);
        return true;
    }
    Node* cur = *head;
    while (cur->next && cur->next->data != val) {
        cur = cur->next;
    }
    if (!cur->next) return false;
    Node* tmp = cur->next;
    cur->next = cur->next->next;
    free(tmp);
    return true;
}

bool delete_at_position(Node** head, int pos, int* val) {
    if (!*head || pos < 1) return false;
    if (pos == 1) return delete_beginning(head, val);
    Node* cur = *head;
    for (int i = 1; cur && i < pos - 1; i++) {
        cur = cur->next;
