                printf("Stack element count: %d\n", s->top + 1);
                break;
            case 0:
                printf("Exiting Array Stack Menu.\n");
                break;
            default:
                printf("Invalid choice.\n");
                break;
        }
    } while (choice != 0);

    stack_free(s);
    return 0;
