                    if (ht_delete(ht, key_buf)) printf("Deleted key '%s'.\n", key_buf);
                    else printf("Key '%s' not found.\n", key_buf);
                } else clear_input();
                break;
            case 4:
                ht_display(ht);
                break;
            case 0:
                printf("Exiting Hash Table Menu.\n");
                break;
            default:
                printf("Invalid choice.\n");
                break;
        }
    } while (choice != 0);

    ht_free(ht);
    return 0;
